VF=["Verdadeiro","Falso"]
# (área, enunciado, alternativas, índice correto, dica, explicação, extras)
F=[
# ---------------- Densidade e massa específica (de) ----------------
("de","Qual é a diferença entre massa específica e densidade?",["A massa específica é uma propriedade da substância; a densidade é calculada para o corpo inteiro, que pode ser oco ou de vários materiais.","Não há nenhuma diferença: são sempre iguais.","A massa específica mede o peso, e a densidade mede o volume.","A densidade só vale para gases, e a massa específica só para sólidos."],0,"Pense em uma bola de ferro maciça e em outra oca.","A massa específica (μ = m/V) é característica do material. A densidade (d = m/V) é a razão entre a massa e o volume do corpo todo; ela só coincide com a massa específica se o corpo for maciço e homogêneo.",{}),
("de","Verdadeiro ou falso: um objeto de ferro oco pode ter densidade menor que a massa específica do ferro.",VF,0,"O volume do objeto inclui a parte vazia.","A cavidade aumenta o volume sem aumentar a massa. Por isso a densidade do corpo fica menor que a massa específica do ferro.",{"v":1}),
("de","Qual é a unidade de massa específica no Sistema Internacional?",["kg/m³","kg·m³","N/m²","g/s"],0,"Massa dividida por volume.","Como μ = m/V, a unidade no SI é quilograma por metro cúbico (kg/m³).",{}),
("de","Por que um navio de aço, feito de um material muito mais denso que a água, flutua?",["Porque o navio, com seu interior cheio de ar, tem densidade média menor que a da água.","Porque o aço flutua na água.","Porque o navio não tem peso.","Porque a água do mar é mais densa que o aço."],0,"Considere o navio inteiro, e não só o aço do casco.","O casco é oco. A densidade do conjunto (aço mais ar) é menor que a da água, e por isso o navio flutua.",{}),
("de","Dois blocos têm o mesmo volume: um de madeira e outro de chumbo. Qual tem maior massa?",["O de chumbo, porque o chumbo tem maior massa específica.","O de madeira, porque é mais leve.","Os dois têm a mesma massa.","Depende apenas da cor."],0,"Use m = μ·V com o mesmo V.","Com volumes iguais, quem tem maior massa específica tem maior massa. O chumbo é bem mais denso que a madeira.",{}),
("de","Verdadeiro ou falso: 1 g/cm³ equivale a 1000 kg/m³.",VF,0,"Converta gramas em quilogramas e centímetros cúbicos em metros cúbicos.","1 g = 10⁻³ kg e 1 cm³ = 10⁻⁶ m³. Assim, 1 g/cm³ = 10⁻³ / 10⁻⁶ kg/m³ = 1000 kg/m³.",{"v":1}),
("de","Uma barra de alumínio maciça é cortada ao meio. A massa específica de cada metade, em comparação com a da barra inteira:",["É a mesma.","É a metade.","É o dobro.","É nula."],0,"A massa específica é característica do material.","Massa e volume caem pela metade, mas a razão m/V continua igual. A massa específica é propriedade do material.",{}),
("de","Por que o óleo de cozinha fica por cima da água quando os dois se misturam?",["Porque o óleo é menos denso que a água.","Porque o óleo é mais denso que a água.","Porque o óleo não tem massa.","Porque a água é mais leve que o ar."],0,"Compare as massas específicas das duas substâncias.","O óleo tem massa específica menor que a da água (cerca de 0,9 g/cm³). Por isso ele fica por cima.",{}),
("de","Ao colocar os materiais abaixo em um balde com água (1,0 g/cm³), qual deles afunda?",["Ferro (7,8 g/cm³).","Gelo (0,92 g/cm³).","Madeira (0,6 g/cm³).","Cortiça (0,2 g/cm³)."],0,"Afunda o que é mais denso que a água.","Só o ferro tem massa específica maior que a da água, então só ele afunda.",{}),
("de","Um bloco de 500 g ocupa um volume de 250 cm³. Qual é a massa específica do material?",["2 g/cm³","0,5 g/cm³","125 g/cm³","0,002 g/cm³"],0,"Use μ = m / V.","μ = 500 g / 250 cm³ = 2 g/cm³.",{"c":1}),
("de","Qual é a massa de 2 m³ de água, sabendo que a massa específica da água é 1000 kg/m³?",["2000 kg","500 kg","2 kg","20 kg"],0,"Use m = μ·V.","m = 1000 kg/m³ × 2 m³ = 2000 kg.",{"c":1}),
# ---------------- Pressão (pr) ----------------
("pr","A pressão exercida por uma força sobre uma superfície é definida como:",["A força perpendicular à superfície dividida pela área.","A força multiplicada pela área.","A massa dividida pelo volume.","A área dividida pela força."],0,"Pressão é força por unidade de área.","p = F / A, em que F é a componente da força perpendicular à superfície.",{"f":"pressao_area"}),
("pr","Qual é a unidade de pressão no Sistema Internacional?",["Pascal (Pa), igual a 1 N/m².","Newton (N).","Joule (J).","Watt (W)."],0,"Pressão é força por área.","A unidade é o pascal: 1 Pa = 1 N/m².",{}),
("pr","Por que uma faca bem afiada corta melhor que uma sem fio, aplicando a mesma força?",["Porque a área de contato é menor e a pressão, maior.","Porque a faca afiada pesa mais.","Porque a faca afiada tem mais massa específica.","Porque a pressão não depende da área."],0,"Na fórmula p = F/A, o que acontece se A diminui?","Com a mesma força, uma área menor produz uma pressão maior, e a faca penetra mais facilmente.",{}),
("pr","Verdadeiro ou falso: aumentando a área de apoio e mantendo a mesma força, a pressão aumenta.",VF,1,"Observe a área no denominador de p = F/A.","A área está no denominador. Com a mesma força, uma área maior leva a uma pressão menor.",{"v":1}),
("pr","Por que as raquetes de neve ajudam a pessoa a não afundar?",["Porque aumentam a área de apoio e diminuem a pressão sobre a neve.","Porque diminuem o peso da pessoa.","Porque aumentam a pressão sobre a neve.","Porque a neve fica mais dura com o calor."],0,"O peso é o mesmo; o que muda é a área.","O peso da pessoa é o mesmo, mas ele se distribui por uma área maior. Com isso, a pressão sobre a neve diminui.",{}),
("pr","Verdadeiro ou falso: a pressão é uma grandeza vetorial.",VF,1,"Ela tem direção e sentido?","A pressão é uma grandeza escalar. A força é que é vetorial; só sua componente perpendicular entra no cálculo.",{"v":1}),
("pr","Por que os pregos têm a ponta fina?",["Para que a força se concentre em uma área pequena e a pressão seja grande.","Para diminuir a pressão sobre a madeira.","Para que o prego fique mais leve.","Para que a pressão seja igual em todos os pontos."],0,"Pense na área de contato da ponta.","A ponta tem área muito pequena. Com isso, a pressão sobre a madeira é muito alta, e o prego entra mais fácil.",{}),
("pr","Em um líquido em repouso, a pressão aumenta com:",["A profundidade.","A altura acima da superfície.","A cor do líquido.","A temperatura ambiente apenas."],0,"É o teorema de Stevin: p = p₀ + μ·g·h.","Quanto mais fundo, maior o peso da coluna de líquido acima, e maior é a pressão.",{"f":"hidro"}),
("pr","Uma força de 200 N age perpendicularmente sobre uma área de 0,5 m². Qual é a pressão?",["400 Pa","100 Pa","40 Pa","0,0025 Pa"],0,"Use p = F / A.","p = 200 N / 0,5 m² = 400 Pa.",{"c":1}),
("pr","Uma caixa de peso 60 N está apoiada sobre uma face de 0,3 m². Qual é a pressão que ela exerce no piso?",["200 Pa","18 Pa","20 Pa","180 Pa"],0,"Aqui a força é o peso da caixa.","p = 60 N / 0,3 m² = 200 Pa.",{"c":1}),
("pr","Qual é a pressão exercida por uma coluna de água de 5 m de altura (μ = 1000 kg/m³ e g = 10 m/s²), sem contar a pressão atmosférica?",["5 × 10⁴ Pa","5 × 10³ Pa","2 × 10⁻³ Pa","5 × 10⁵ Pa"],0,"Use p = μ·g·h.","p = 1000 × 10 × 5 = 5 × 10⁴ Pa.",{"c":1}),
# ---------------- Pressão atmosférica (pa) ----------------
("pa","A pressão atmosférica existe porque:",["O ar tem peso e a camada de ar sobre nós exerce pressão.","O ar não tem massa.","A Terra gira.","O vento sopra sempre para baixo."],0,"Pense na camada de ar acima de você.","O ar tem massa, e a Terra o atrai. O peso da coluna de ar acima de nós gera a pressão atmosférica.",{}),
("pa","Ao subir uma montanha, a pressão atmosférica:",["Diminui.","Aumenta.","Fica constante.","Fica sempre nula."],0,"Compare a quantidade de ar acima de você em baixo e no alto.","Quanto mais alto, menos ar há acima, e menor é a pressão atmosférica.",{}),
("pa","Verdadeiro ou falso: ao nível do mar, a pressão atmosférica vale aproximadamente 1,0 × 10⁵ Pa (1 atm).",VF,0,"É a pressão normal que usamos como referência.","O valor normal é 1 atm, que corresponde a cerca de 1,0 × 10⁵ Pa.",{"v":1}),
("pa","Por que é possível beber um refresco usando um canudo?",["Ao sugar, a pressão dentro do canudo diminui e a pressão atmosférica empurra o líquido para cima.","Porque o líquido é puxado pela boca, sem influência do ar.","Porque o canudo é mais leve que o líquido.","Porque o líquido sobe sozinho por ser denso."],0,"Pense na diferença de pressão entre a boca e a superfície do líquido.","Ao sugar, reduzimos a pressão no canudo. A pressão atmosférica sobre a superfície do líquido é maior e o empurra pelo canudo.",{}),
("pa","Por que os ouvidos “estalam” quando um carro sobe ou desce uma serra?",["Porque a pressão do ar externo muda e o ar do ouvido médio se ajusta a essa diferença.","Porque a temperatura do ar muda.","Porque a massa específica do corpo muda.","Porque o som viaja mais rápido na serra."],0,"Pense na pressão atmosférica em alturas diferentes.","A pressão externa varia com a altitude. O ouvido médio precisa equilibrar essa diferença, e isso produz o estalo.",{}),
("pa","Verdadeiro ou falso: a pressão atmosférica atua apenas de cima para baixo.",VF,1,"Pense em um balão de gás cheio.","Como o ar é um fluido, a pressão atua em todas as direções, de cima, de baixo e dos lados.",{"v":1}),
("pa","Uma ventosa gruda em um vidro liso porque:",["A pressão atmosférica externa é maior que a pressão do ar que sobrou dentro dela.","A ventosa tem cola.","O vidro é magnético.","A pressão atmosférica não existe."],0,"Ao apertar a ventosa, parte do ar sai.","Ao pressionar, o ar sai e a pressão interna diminui. A pressão atmosférica de fora é maior e mantém a ventosa colada.",{}),
("pa","Em qual lugar a pressão atmosférica é maior?",["Em uma cidade litorânea, ao nível do mar.","No topo de uma montanha alta.","Em um avião a 10 000 m de altitude.","No espaço, fora da atmosfera."],0,"Quanto mais baixo, mais ar acima de você.","Ao nível do mar, a coluna de ar acima é maior, e por isso a pressão é maior.",{}),
("pa","Por que astronautas precisam usar trajes pressurizados no espaço?",["Porque lá fora não há pressão atmosférica para equilibrar a pressão do corpo.","Porque o espaço é muito quente.","Porque lá a pressão atmosférica é enorme.","Porque lá o ar é muito denso."],0,"Fora da atmosfera a pressão externa é praticamente nula.","Sem o traje, a pressão interna do corpo não teria equilíbrio com o meio externo. O traje mantém uma pressão adequada.",{}),
("pa","A panela de pressão cozinha os alimentos mais depressa porque:",["Com a pressão maior, a água ferve a uma temperatura mais alta.","A água fica sem peso.","A pressão diminui dentro da panela.","O alimento fica mais leve."],0,"Pressão e ponto de ebulição estão ligados.","Dentro da panela, a pressão é maior que a atmosférica e a água só ferve a uma temperatura mais alta, o que acelera o cozimento.",{}),
# ---------------- Experimento de Torricelli (to) ----------------
("to","No experimento de Torricelli, o que se usa para medir a pressão atmosférica?",["Um tubo de vidro cheio de mercúrio, emborcado em uma cuba com mercúrio.","Uma balança de dois pratos.","Um tubo vazio mergulhado na água.","Uma mola presa ao teto."],0,"O líquido usado é muito denso.","O tubo fechado em uma ponta e cheio de mercúrio é virado em uma cuba com mercúrio. A coluna desce e para em uma altura que depende da pressão atmosférica.",{"f":"torricelli"}),
("to","Ao nível do mar, a altura da coluna de mercúrio no experimento de Torricelli é de aproximadamente:",["76 cm.","10 m.","1 cm.","760 m."],0,"É o valor que define 1 atm em mmHg.","Ao nível do mar, a coluna tem cerca de 76 cm (760 mm) de mercúrio.",{"f":"torricelli"}),
("to","O que existe no espaço acima do mercúrio, no topo do tubo de Torricelli?",["Praticamente vácuo.","Ar com pressão de 1 atm.","Água.","Mercúrio líquido comprimido."],0,"O mercúrio desceu e deixou um espaço.","Quando o mercúrio desce, o espaço no topo fica praticamente vazio. É o chamado vácuo de Torricelli.",{"f":"torricelli"}),
("to","Verdadeiro ou falso: inclinar o tubo no experimento de Torricelli muda a altura vertical da coluna de mercúrio.",VF,1,"A pressão depende da altura vertical.","A altura vertical é determinada pela pressão atmosférica e não muda. O comprimento do mercúrio no tubo é que aumenta, mas a altura vertical é a mesma.",{"v":1}),
("to","Se o experimento de Torricelli for feito no alto de uma montanha, a coluna de mercúrio:",["Fica menor que 76 cm.","Fica maior que 76 cm.","Continua exatamente com 76 cm.","Desaparece."],0,"A pressão atmosférica diminui com a altitude.","No alto da montanha, a pressão atmosférica é menor e sustenta uma coluna menor de mercúrio.",{}),
("to","Por que Torricelli usou mercúrio em vez de água?",["Porque o mercúrio é muito mais denso, e a coluna fica pequena e fácil de manusear.","Porque o mercúrio é mais leve que a água.","Porque a água evapora no experimento sem outro motivo.","Porque o mercúrio não tem massa."],0,"Compare as massas específicas dos dois líquidos.","O mercúrio é cerca de 13,6 vezes mais denso que a água. Com água, a coluna teria cerca de 10 m, e com mercúrio tem 76 cm.",{}),
("to","A pressão de 1 atm equivale a:",["760 mmHg.","76 mmHg.","7600 mmHg.","1 mmHg."],0,"Relacione com a altura da coluna de mercúrio.","A coluna de 760 mm de mercúrio equilibra a pressão atmosférica normal, então 1 atm = 760 mmHg.",{}),
("to","Verdadeiro ou falso: no experimento de Torricelli, a pressão exercida pela coluna de mercúrio equilibra a pressão atmosférica.",VF,0,"É o equilíbrio que mantém a coluna parada.","A pressão da coluna (μ·g·h) é igual à pressão atmosférica que atua na superfície do mercúrio da cuba.",{"v":1,"f":"torricelli"}),
("to","Se um tubo de Torricelli mais largo for usado, a altura da coluna de mercúrio:",["Continua a mesma.","Aumenta.","Diminui.","Passa a ser nula."],0,"A pressão não depende da largura do tubo.","A altura depende da pressão atmosférica e da massa específica do líquido, e não da largura ou da forma do tubo.",{}),
("to","Se o experimento de Torricelli fosse feito com água, qual seria, aproximadamente, a altura da coluna ao nível do mar? (p = 1,0 × 10⁵ Pa, μ = 1000 kg/m³, g = 10 m/s²)",["10 m","0,76 m","1 m","100 m"],0,"Use p = μ·g·h e isole h.","h = p / (μ·g) = 10⁵ / (1000 × 10) = 10 m.",{"c":1}),
# ---------------- Cientistas e história (cs) ----------------
("cs","Quem é o cientista desenhado na figura, que realizou o experimento do barômetro de mercúrio?",["Evangelista Torricelli","Blaise Pascal","Arquimedes","Simon Stevin"],0,"Ele viveu na Itália, no século XVII, e foi discípulo de Galileu.","Evangelista Torricelli (1608–1647), físico italiano, realizou em 1643 o experimento que mostrou a existência da pressão atmosférica e inventou o barômetro de mercúrio.",{"f":"ret_torricelli"}),
("cs","Quem é o cientista desenhado na figura, que dá nome à unidade de pressão do SI?",["Blaise Pascal","Evangelista Torricelli","Arquimedes","Simon Stevin"],0,"A unidade de pressão no SI é o pascal.","Blaise Pascal (1623–1662), francês, estudou a pressão nos fluidos. A unidade de pressão do SI recebeu o nome dele.",{"f":"ret_pascal"}),
("cs","Quem é o cientista desenhado na figura, famoso pelo princípio do empuxo e pela história da coroa do rei?",["Arquimedes","Blaise Pascal","Evangelista Torricelli","Simon Stevin"],0,"Viveu em Siracusa, na Grécia antiga.","Arquimedes (cerca de 287–212 a.C.) formulou o princípio do empuxo: um corpo mergulhado em um fluido recebe uma força para cima igual ao peso do fluido deslocado.",{"f":"ret_arquimedes"}),
("cs","Quem é o cientista desenhado na figura, que mostrou que a pressão em um líquido aumenta com a profundidade (teorema fundamental da hidrostática)?",["Simon Stevin","Blaise Pascal","Arquimedes","Evangelista Torricelli"],0,"O teorema fundamental da hidrostática leva o nome dele.","Simon Stevin (1548–1620), flamengo, estudou a pressão nos líquidos. O teorema de Stevin diz que a pressão aumenta com a profundidade: p = p₀ + μ·g·h.",{"f":"ret_stevin"}),
("cs","Verdadeiro ou falso: Pascal pediu que o experimento de Torricelli fosse repetido em uma montanha, e a coluna de mercúrio ficou menor lá em cima.",VF,0,"A pressão atmosférica diminui com a altitude.","Em 1648, a pedido de Pascal, o experimento foi repetido na montanha Puy de Dôme, e a coluna ficou menor. Isso confirmou que a pressão atmosférica diminui com a altitude.",{"v":1}),
]
